const query = $json.query || {};
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];
if (!challenge || token !== $env.Criccheto_WHATSAPP_VERIFY_TOKEN) {
  throw new Error('Invalid WhatsApp verification request');
}
return [{ json: { challenge } }];

const envelope = $json;
const body = envelope.body || envelope;
const headers = envelope.headers || {};

function header(name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (String(key).toLowerCase() === target) return value;
  }
  return undefined;
}

function ignored(reason) {
  return { ignored: true, reason };
}

function safeString(value) {
  return typeof value === 'string' ? value : '';
}

function safeNumber(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

function normalizeWhatsApp(payload) {
  if (payload.object !== 'whatsapp_business_account') return null;
  if (header('x-upstream-verified-meta-signature') !== '1') {
    throw new Error('Missing upstream WhatsApp signature verification');
  }
  const value = payload.entry?.[0]?.changes?.[0]?.value;
  if (!value) return ignored('unsupported_whatsapp_payload');
  if (Array.isArray(value.statuses) && value.statuses.length > 0 && !value.messages?.length) {
    return ignored('whatsapp_status_event');
  }
  const message = value.messages?.[0];
  if (!message) return ignored('unsupported_whatsapp_payload');

  const attachments = [];
  let text = '';

  if (message.type === 'text' && message.text?.body) {
    text = message.text.body;
  } else if (message.type === 'image' && message.image?.id) {
    text = safeString(message.image.caption);
    attachments.push({
      attachmentType: 'photo',
      providerMediaId: message.image.id,
      mimeType: message.image.mime_type || null,
      fileSize: safeNumber(message.image.file_size),
      caption: safeString(message.image.caption) || null,
    });
  } else if (message.type === 'document' && message.document?.id) {
    text = safeString(message.document.caption);
    attachments.push({
      attachmentType: 'document',
      providerMediaId: message.document.id,
      filename: message.document.filename || null,
      mimeType: message.document.mime_type || null,
      fileSize: safeNumber(message.document.file_size),
      caption: safeString(message.document.caption) || null,
    });
  } else if (message.type === 'audio' && message.audio?.id) {
    attachments.push({
      attachmentType: 'audio',
      providerMediaId: message.audio.id,
      mimeType: message.audio.mime_type || null,
      fileSize: safeNumber(message.audio.file_size),
    });
  } else if (message.type === 'video' && message.video?.id) {
    text = safeString(message.video.caption);
    attachments.push({
      attachmentType: 'other',
      providerMediaId: message.video.id,
      mimeType: message.video.mime_type || null,
      fileSize: safeNumber(message.video.file_size),
      caption: safeString(message.video.caption) || null,
    });
  } else {
    return ignored('unsupported_whatsapp_message_type');
  }

  return {
    channel: 'whatsapp',
    provider: $env.Criccheto_WHATSAPP_PROVIDER || 'meta_whatsapp_cloud_api',
    providerMessageId: message.id,
    senderIdentifier: message.from,
    recipientIdentifier: value.metadata?.phone_number_id || $env.Criccheto_WHATSAPP_PHONE_NUMBER_ID,
    text,
    attachments,
    rawPayload: payload
  };
}

function normalizeTelegram(payload) {
  const secret = header('x-telegram-bot-api-secret-token');
  if ($env.Criccheto_TELEGRAM_WEBHOOK_SECRET && secret !== $env.Criccheto_TELEGRAM_WEBHOOK_SECRET) {
    throw new Error('Invalid Telegram webhook secret');
  }
  const message = payload.message || payload.edited_message;
  if (message) {
    const attachments = [];
    let text = safeString(message.text || message.caption);

    if (Array.isArray(message.photo) && message.photo.length > 0) {
      const photo = [...message.photo]
        .filter((entry) => entry?.file_id)
        .sort((left, right) => Number(right?.file_size || 0) - Number(left?.file_size || 0))[0];
      if (photo?.file_id) {
        attachments.push({
          attachmentType: 'photo',
          providerFileId: photo.file_id,
          providerFileUniqueId: photo.file_unique_id || null,
          mimeType: 'image/jpeg',
          fileSize: safeNumber(photo.file_size),
          caption: safeString(message.caption) || null,
        });
      }
    } else if (message.document?.file_id) {
      attachments.push({
        attachmentType: 'document',
        providerFileId: message.document.file_id,
        providerFileUniqueId: message.document.file_unique_id || null,
        filename: message.document.file_name || null,
        mimeType: message.document.mime_type || null,
        fileSize: safeNumber(message.document.file_size),
        caption: safeString(message.caption) || null,
      });
    } else if (message.audio?.file_id) {
      attachments.push({
        attachmentType: 'audio',
        providerFileId: message.audio.file_id,
        providerFileUniqueId: message.audio.file_unique_id || null,
        filename: message.audio.file_name || null,
        mimeType: message.audio.mime_type || null,
        fileSize: safeNumber(message.audio.file_size),
        caption: safeString(message.caption) || null,
      });
    } else if (message.voice?.file_id) {
      attachments.push({
        attachmentType: 'audio',
        providerFileId: message.voice.file_id,
        providerFileUniqueId: message.voice.file_unique_id || null,
        filename: 'voice-message.ogg',
        mimeType: message.voice.mime_type || 'audio/ogg',
        fileSize: safeNumber(message.voice.file_size),
        caption: safeString(message.caption) || null,
      });
    } else if (message.video?.file_id) {
      attachments.push({
        attachmentType: 'other',
        providerFileId: message.video.file_id,
        providerFileUniqueId: message.video.file_unique_id || null,
        filename: message.video.file_name || 'telegram-video.mp4',
        mimeType: message.video.mime_type || 'video/mp4',
        fileSize: safeNumber(message.video.file_size),
        caption: safeString(message.caption) || null,
      });
    } else if (!text) {
      return ignored('unsupported_telegram_message_type');
    }

    return {
      channel: 'telegram_test',
      provider: 'telegram_bot_api',
      providerMessageId: String(message.message_id),
      senderIdentifier: String(message.chat?.id),
      recipientIdentifier: payload.recipient || payload.bot_username || $env.Criccheto_TELEGRAM_BOT_IDENTIFIER || 'Cricchetto_bot',
      text,
      attachments,
      rawPayload: payload
    };
  }
  if (payload.callback_query) {
    return ignored('unsupported_telegram_callback');
  }
  if (payload.update_id) return ignored('unsupported_telegram_update');
  return null;
}

const normalized = normalizeWhatsApp(body) || normalizeTelegram(body);
if (!normalized) throw new Error('Unsupported inbound provider payload');
if (normalized.ignored) return [{ json: normalized }];
if (!normalized.providerMessageId || !normalized.senderIdentifier || !normalized.recipientIdentifier || !(normalized.text || normalized.attachments?.length)) {
  throw new Error('Normalized inbound payload is incomplete');
}
return [{ json: normalized }];

