const messages = $json.outboundMessages || [];
if (!Array.isArray(messages)) throw new Error('Backend process-inbound response must include outboundMessages array');
return messages.map((message) => {
  for (const field of ['messageLogId', 'channel', 'provider', 'recipientIdentifier', 'text']) {
    if (!message[field]) throw new Error(`Queued outbound message missing ${field}`);
  }
  return { json: message };
});
